import re
from datetime import datetime

_GMAIL_DOMAINS = {"gmail.com", "googlemail.com"}
_DATE_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")
_DIGITS = "0123456789"


def _get(row, key):
    value = row.get(key)
    return "" if value is None else str(value)


def _is_digits(s):
    return bool(s) and all(c in _DIGITS for c in s)


def _normalize_email(raw):
    text = raw
    match = re.search(r"<([^<>]*)>", text)
    if match:
        text = match.group(1)
    text = text.strip().lower()
    # Gmail rules apply only to well-formed addresses (exactly one "@").
    if text.count("@") == 1:
        local, domain = text.split("@")
        if domain in _GMAIL_DOMAINS:
            local = local.replace(".", "").split("+", 1)[0]
            text = f"{local}@gmail.com"
    return text


def _is_valid_email(email):
    if email.count("@") != 1:
        return False
    local, domain = email.split("@")
    return (
        bool(local)
        and "." in domain
        and not domain.startswith(".")
        and not domain.endswith(".")
    )


def _normalize_phone(raw):
    match = re.search(r"ext|x|#", raw, flags=re.IGNORECASE)
    if match:
        raw = raw[:match.start()]
    digits = "".join(c for c in raw if c in _DIGITS)
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    return digits


def _is_valid_phone(phone):
    return len(phone) == 10 and phone[0] not in "01"


def _normalize_zip(raw):
    zip_code = raw.strip()
    match = re.fullmatch(r"([0-9]+)-[0-9]{4}", zip_code)
    if match:
        zip_code = match.group(1)
    if len(zip_code) == 4 and _is_digits(zip_code):
        zip_code = "0" + zip_code
    if len(zip_code) == 5 and _is_digits(zip_code):
        return zip_code
    return ""


def _normalize_name(raw):
    name = raw.strip()
    if name.isupper() or name.islower():
        name = name.title()
    return name


def _parse_updated(raw):
    text = raw.strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(text, fmt)
        except ValueError:
            pass
    return datetime.min  # unparseable: sorts as oldest


def _parse_tags(raw):
    parts = re.split(r"[;,]", raw)
    return [p.strip().lower() for p in parts if p.strip()]


def _pick(members, field):
    """Prefer manual rows, then most recent updated, then earliest input row."""
    candidates = [m for m in members if m[field]]
    if not candidates:
        return ""
    best = max(candidates, key=lambda m: (m["manual"], m["updated"], -m["index"]))
    return best[field]


def dedupe_contacts(rows):
    # Normalize each row and drop rows with neither a valid email nor a valid phone.
    kept = []
    for index, row in enumerate(rows):
        email = _normalize_email(_get(row, "email"))
        phone = _normalize_phone(_get(row, "phone"))
        has_email = _is_valid_email(email)
        has_phone = _is_valid_phone(phone)
        if not (has_email or has_phone):
            continue

        source = _get(row, "source").strip().lower()
        kept.append({
            "index": index,
            "first_name": _normalize_name(_get(row, "first_name")),
            "last_name": _normalize_name(_get(row, "last_name")),
            "zip": _normalize_zip(_get(row, "zip")),
            "email": email if has_email else "",
            "phone": phone if has_phone else "",
            "source": source,
            "manual": source == "manual",
            "tags": _parse_tags(_get(row, "tags")),
            "opted_out": _get(row, "opted_out").strip().lower() in ("y", "yes", "true", "1"),
            "updated": _parse_updated(_get(row, "updated")),
        })

    # Union-find: rows sharing a valid email, or a valid phone plus the same
    # non-empty last name (case-insensitive), belong to the same person.
    parent = list(range(len(kept)))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        root_a, root_b = find(a), find(b)
        if root_a != root_b:
            parent[max(root_a, root_b)] = min(root_a, root_b)

    first_by_email = {}
    first_by_phone_last = {}
    for pos, rec in enumerate(kept):
        if rec["email"]:
            if rec["email"] in first_by_email:
                union(pos, first_by_email[rec["email"]])
            else:
                first_by_email[rec["email"]] = pos
        if rec["phone"] and rec["last_name"]:
            key = (rec["phone"], rec["last_name"].lower())
            if key in first_by_phone_last:
                union(pos, first_by_phone_last[key])
            else:
                first_by_phone_last[key] = pos

    # Group rows. Dict insertion order follows each group's earliest input row.
    groups = {}
    for pos in range(len(kept)):
        groups.setdefault(find(pos), []).append(kept[pos])

    results = []
    for members in groups.values():
        tags = sorted({t for m in members for t in m["tags"]})
        results.append({
            "first_name": _pick(members, "first_name"),
            "last_name": _pick(members, "last_name"),
            "zip": _pick(members, "zip"),
            "email": _pick(members, "email"),
            "phone": _pick(members, "phone"),
            "source": _pick(members, "source"),
            "tags": ";".join(tags),
            "opted_out": "Y" if any(m["opted_out"] for m in members) else "N",
            "updated": max(m["updated"] for m in members).strftime("%Y-%m-%d"),
        })

    return results
